    "/shop/ai/shelf-photo": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * One-shot onboarding. Photo(s) of shelves/counter -> detected products matched to the shared catalogue,
         *     each with a visible-count estimate. Owner confirms (one tap per row), then client calls POST /shop/products/bulk
         *     with count_source = photo_estimate. Suggest only, never writes stock.
         *     Counts only cover what is visible from the front, so treat as an estimate, not a precise stock.
         */
        post: {
            parameters: {
                query?: {
                    /**
                     * @description true (default): after reading the whole photo, re-read four zoomed overlapping tiles to identify
                     *     small labels (about 5 AI calls per photo, roughly 20 s). Counts still come from the whole-photo read.
                     *     false: single fast read.
                     */
                    thorough?: boolean;
                };
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "multipart/form-data": {
                        images: string[];
                    };
                };
            };
            responses: {
                /** @description OK */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            detections?: {
                                /** @description What the model saw, e.g. 'Lux soap pink 100g' */
                                label?: string;
                                /** @description Best catalogue match, null if none */
                                match?: components["schemas"]["Product"] | null;
                                /** @description Other candidate matches for a one-tap swap */
                                alternatives?: components["schemas"]["Product"][];
                                /** @description Facings/units counted in the photo */
                                visible_count?: number;
                                /** @enum {string} */
                                suggested_level?: "plenty" | "some" | "few";
                                confidence?: number;
                                /**
                                 * Format: double
                                 * @description Pre-filled price for the confirm list: the printed MRP, else the median price other shops charge. null when neither is known (the owner types one). Never invented.
                                 */
                                suggested_price?: number | null;
                                /** @enum {string|null} */
                                price_source?: "mrp" | "nearby_median" | null;
                                /** @description What the model read from the label, split out. Use it to offer 'add as a new product' when `match` is null; the owner confirms. */
                                read?: {
                                    brand?: string;
                                    name?: string;
                                    size?: string;
                                    category?: string;
                                };
                                /** @description False when the model was only guessing from shape or colour: do not pre-select these */
                                readable?: boolean;
                                /** @description True when the matched product is already in this shop. Onboarding skips it; offer a recount instead (POST /shop/recount). */
                                in_shop?: boolean;
                                /** @description The system's count for an in_shop item, in base units */
                                current_quantity?: number | null;
                                /** @enum {string|null} */
                                current_status?: "in_stock" | "low" | "out" | null;
                                /** @description Unlabelled goods (produce, eggs, sacks). `match` is one of the shop's loose tiles, or null when there is no tile yet. Never needs a barcode scan. */
                                loose?: boolean;
                                /** @description The model named a brand but could not read the pack clearly. `alternatives` are suggestions to confirm, never an automatic match. */
                                uncertain?: boolean;
                                /** @description True when no confident match: UI prompts the owner to scan this item's barcode */
                                needs_scan?: boolean;
                            }[];
                            /**
                             * @description Prompt the owner to retake when not good
                             * @enum {string}
                             */
                            image_quality?: "good" | "blurry" | "too_dark" | "too_far";
                        };
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
